import{_ as e,o,c as n,ah as a}from"./chunks/framework.Dpoi9ndL.js";const s="/projects/uHandPi/en/latest/assets/image1.BMUQlYkL.webp",i="/projects/uHandPi/en/latest/assets/image2.Dr38LNV2.webp",r="/projects/uHandPi/en/latest/assets/image3.BdsUFbP3.webp",d="/projects/uHandPi/en/latest/assets/image4.D7Xp7RU-.webp",l="/projects/uHandPi/en/latest/assets/image5.DfIa_C4o.webp",c="data:image/png;base64,",A="/projects/uHandPi/en/latest/assets/image7.iKsJ1XDW.webp",g="/projects/uHandPi/en/latest/assets/image8.B2NmM6DL.webp",h="/projects/uHandPi/en/latest/assets/image9.CNI4wbms.webp",m="/projects/uHandPi/en/latest/assets/image10.v4JEf8BE.webp",p="/projects/uHandPi/en/latest/assets/image11.Bq64QiLz.webp",u="/projects/uHandPi/en/latest/assets/image12.BTAxY_l8.webp",b="/projects/uHandPi/en/latest/assets/image13.lWbC1vxj.webp",y="/projects/uHandPi/en/latest/assets/image14.CKPsNyb2.webp",C="/projects/uHandPi/en/latest/assets/image15.BD2zKp_Y.webp",w="data:image/png;base64,",f="data:image/png;base64,",U="data:image/png;base64,",k="data:image/png;base64,",q="/projects/uHandPi/en/latest/assets/image20.-wElpCwW.webp",I="data:image/png;base64,",B="data:image/png;base64,",R="data:image/png;base64,",P="/projects/uHandPi/en/latest/assets/image24.F74YNLsI.webp",v="/projects/uHandPi/en/latest/assets/image1.DFBQQlkk.webp",D="/projects/uHandPi/en/latest/assets/image2.CQw5ED8X.webp",x="/projects/uHandPi/en/latest/assets/image4.BEXSqNXh.webp",E="/projects/uHandPi/en/latest/assets/image5.BlW8t16g.webp",V="/projects/uHandPi/en/latest/assets/image6.MJQJRs2e.webp",z="/projects/uHandPi/en/latest/assets/image8.FdK78CW3.webp",F="/projects/uHandPi/en/latest/assets/image9.DGQbgRML.webp",S=JSON.parse('{"title":"3. Remote Desktop Installation and Connection","description":"","frontmatter":{},"headers":[],"relativePath":"docs/6.remote_tool_installation_and_connection.md","filePath":"docs/6.remote_tool_installation_and_connection.md"}'),G={name:"docs/6.remote_tool_installation_and_connection.md"};function W(X,t,Q,T,j,H){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_3-remote-desktop-installation-and-connection" tabindex="-1">3. Remote Desktop Installation and Connection <a class="header-anchor" href="#_3-remote-desktop-installation-and-connection" aria-label="Permalink to &quot;3. Remote Desktop Installation and Connection&quot;">​</a></h1><h2 id="_3-1-vnc-installation-and-connection" tabindex="-1">3.1 VNC Installation and Connection <a class="header-anchor" href="#_3-1-vnc-installation-and-connection" aria-label="Permalink to &quot;3.1 VNC Installation and Connection&quot;">​</a></h2><h3 id="_3-1-1-preparation" tabindex="-1">3.1.1 Preparation <a class="header-anchor" href="#_3-1-1-preparation" aria-label="Permalink to &quot;3.1.1 Preparation&quot;">​</a></h3><ul><li><strong>Hardware</strong></li></ul><p>Prepare a computer. If you are using desktop computer, wireless network card is required.The network card should support 5G band.</p><ul><li><strong>Install VNC</strong></li></ul><p>VNC is a graphical remote desktop control software. Through connecting your computer to the WiFi generated by Raspberry Pi, you can control Raspberry Pi. Installation of VNC is as below.</p><p>(1) Double-click the installation program &quot;<strong>VNC-Viewer-6.17.731-Windows</strong>&quot; in the same directory as this section. Select the installation language as &quot;<strong>English</strong>&quot; and lick &quot;<strong>OK</strong>&quot;.</p><img loading="lazy" height="151" width="294" class="common_img" src="'+s+'"><p>(2) Click &quot;<strong>Next</strong>&quot;.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+i+'"><p>(3) Tick <strong>&quot;I accept the terms in the License Agreement&quot;</strong>. Then click <strong>&quot;Next&quot;</strong>.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+r+'"><p>(4) Remain default location where the software is installed. Click <strong>&quot;Next&quot;</strong> to proceed next interface. Then directly click <strong>&quot;Install&quot;</strong>.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+d+'"><p>(5) When the installation completes, click <strong>&quot;Finish&quot;</strong>.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+l+'"><p>(6) Click <img loading="lazy" height="69" width="69" src="'+c+'" style="width:45px;"> to open VNC.</p><ul><li><strong>Start Robot</strong></li></ul><p>Start Robot When LED1 on expansion board starts flickering and buzzer emits one beep, robot boots up successfully.</p><h3 id="_3-1-2-connect-to-robot" tabindex="-1">3.1.2 Connect to Robot <a class="header-anchor" href="#_3-1-2-connect-to-robot" aria-label="Permalink to &quot;3.1.2 Connect to Robot&quot;">​</a></h3><p>(1) After turning Robot on successfully, the default mode is AP direct connection mode. Robot generates a WiFi starting with HW. Connect your computer to this WiFi.</p><img loading="lazy" height="58" width="361" class="common_img" src="'+A+'"><p>(2) Input password. The password is <strong>&quot;hiwonder&quot;</strong>.</p><img loading="lazy" height="167" width="360" class="common_img" src="'+g+'"><img loading="lazy" height="135" width="358" class="common_img" src="'+h+'"><p>(3) After connection, open VNC Viewer. Input the default IP address of Raspberry Pi, <strong>192.168.149.1</strong>, and then press Enter. If you receive security warning, select <strong>&quot;Continue&quot;</strong>.</p><img loading="lazy" height="88" width="884" class="common_img" src="'+m+'"><p>(4) Input username and password. <strong>(Username: pi Password: raspberrypi)</strong>. Click <strong>&quot;OK&quot;</strong> to enter Raspberry Pi desktop.</p><img loading="lazy" height="242" width="344" class="common_img" src="'+p+'"><p>(5) The desktop is as pictured. If black screen occurs or only cursor leaves on the screen, restart Raspberry Pi.</p><img loading="lazy" height="678" width="1266" class="common_img" src="'+u+'"><h3 id="_3-1-3-introduction-to-desktop" tabindex="-1">3.1.3 Introduction to Desktop <a class="header-anchor" href="#_3-1-3-introduction-to-desktop" aria-label="Permalink to &quot;3.1.3 Introduction to Desktop&quot;">​</a></h3><p>The desktop is as pictured after connecting Robot through VNC successfully.</p><img loading="lazy" height="731" width="1269" class="common_img" src="'+b+'"><p>The following table demonstrates common functions:</p><table class="docutils-nobg" border="1"><colgroup><col><col></colgroup><tbody><tr><td>Icon</td><td>Function</td></tr><tr><td><img loading="lazy" height="50" width="60" src="'+y+'"></td><td><p>Application menu. Click to select different applications.</p><p><img loading="lazy" height="336" width="211" src="'+C+'"></p></td></tr><tr><td><img loading="lazy" height="49" width="54" src="'+w+'"></td><td>Browser.</td></tr><tr><td><img loading="lazy" height="48" width="57" src="'+f+'"></td><td>File manager.</td></tr><tr><td><img loading="lazy" height="41" width="60" src="'+U+'"></td><td>LX terminal. Click to input command line in the opened interface.</td></tr><tr><td><img loading="lazy" height="50" width="44" src="'+k+'"></td><td>Trash. You can find the files deleted here.</td></tr><tr><td><img loading="lazy" height="70" width="72" src="'+q+'"></td><td>PC software. You can adjust pan tilt and adjust color threshold on it.</td></tr><tr><td><img loading="lazy" height="41" width="29" src="'+I+'"></td><td>Full screen or exit full screen.。</td></tr><tr><td><img loading="lazy" height="34" width="34" src="'+B+'"></td><td>Exit full screen.</td></tr><tr><td><img loading="lazy" height="41" width="32" src="'+R+'"></td><td><p>Shut down, reboot and logout</p><p><img loading="lazy" height="157" width="300" src="'+P+'"></p></td></tr></tbody></table><h2 id="_3-2-system-content" tabindex="-1">3.2 System Content <a class="header-anchor" href="#_3-2-system-content" aria-label="Permalink to &quot;3.2 System Content&quot;">​</a></h2><h3 id="_3-2-1-desktop-layout" tabindex="-1">3.2.1 Desktop Layout <a class="header-anchor" href="#_3-2-1-desktop-layout" aria-label="Permalink to &quot;3.2.1 Desktop Layout&quot;">​</a></h3><p>After connecting to VNC, the system desktop is as pictured:</p><img loading="lazy" height="497" width="883" class="common_img" src="'+v+'"><p>(1) Double-click this icon <img loading="lazy" height="82" width="113" src="'+D+'" style="width:60px;"> and click Execution.</p><p>This tool is used to adjust color threshold parameters and debug the pan-tilt servo.</p><img loading="lazy" height="608" width="883" class="common_img" src="'+x+'"><p>(2) Click <strong>&quot;<strong>Connect</strong>&quot;</strong> to display the real-time image transmitted by the current camera. Then you can click &quot;<strong>Disconnect</strong>&quot; to close the camera.</p><img loading="lazy" height="600" width="883" class="common_img" src="'+E+'"><p>(3) The tool interface can be divided into three parts as follows:</p><table tabindex="0"><thead><tr><th><strong>No.</strong></th><th><strong>Name</strong></th><th><strong>Function</strong></th></tr></thead><tbody><tr><td>①</td><td>Camera feedback area</td><td>Used to display the transmitted image, with the processed image on the left and the original image on the right.</td></tr><tr><td>②</td><td>Adjust color threshold parameters button</td><td>Used for adjusting color thresholds, selecting the colors to be adjusted for recognition, adding or removing color categories, and saving the effects.</td></tr><tr><td>③</td><td>Servo control area</td><td>Used to adjust the initial position of the sixth servo of the pan-tilt and save the modified values.</td></tr></tbody></table><p>You can go to &quot;<a href="https://docs.hiwonder.com/projects/uHandPi/en/latest/docs/2.quick_user_experience.html#adjust-color-threshold" target="_blank" rel="noreferrer"><strong>Quick User Experience\\2.3 Adjust Color Threshold</strong></a>&quot; to learn the specific usage method of tool and the color threshold parameter.</p><h3 id="_3-2-2-program-structure-instruction" tabindex="-1">3.2.2 Program Structure Instruction <a class="header-anchor" href="#_3-2-2-program-structure-instruction" aria-label="Permalink to &quot;3.2.2 Program Structure Instruction&quot;">​</a></h3><p>(1) Press <strong>&quot;Ctrl+Alt+T&quot;</strong> to open the command line terminal. And input <strong>&quot;ls&quot;</strong> command to list all the current files. Take following contents as example.</p><img loading="lazy" height="122" width="748" class="common_img" src="'+V+'"><table tabindex="0"><thead><tr><th>Content</th><th>Function</th></tr></thead><tbody><tr><td>hiwonder-toolbox</td><td>WiFi management tool</td></tr><tr><td>uhandpi</td><td>Program source code for all game modes and associated functions.</td></tr><tr><td>uhandpi_software</td><td>Color threshold debugging tool and palm-sized PC.</td></tr></tbody></table><p>(2) Next, enter the game and program source content. Then input the following command.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uhandpi/</span></span></code></pre></div><p>(3) After that, input <strong>&quot;tree-L1&quot;</strong> command. List all folders and files in the directory in the form of a tree diagram. We mainly need to understand several directories indicated by the red box in the diagram.</p><img loading="lazy" height="319" width="366" class="common_img" src="'+z+'"><table tabindex="0"><thead><tr><th><strong>Content/File</strong></th><th><strong>Instruction</strong></th></tr></thead><tbody><tr><td>action_groups</td><td>Action group files storage path</td></tr><tr><td>action_groups</td><td>Expansion board related routine</td></tr><tr><td>camera_calibration_sdk</td><td>Camera underlying file and calibration files</td></tr><tr><td>common_sdk</td><td>Underlying driver library</td></tr><tr><td>common.txt</td><td>Detect and game command</td></tr><tr><td>config</td><td>Color threshold and servo deviation configuration file</td></tr><tr><td>mjpg_server.py</td><td>Video stream program</td></tr><tr><td>rpc_server.py</td><td>Rpc communication service program</td></tr><tr><td>uHandPi.py</td><td>APP service starting file</td></tr></tbody></table><p>(4) Input the command below, and open the directory containing the AI vision game program directly through the tree diagram.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> functions</span></span></code></pre></div><img loading="lazy" height="215" width="433" class="common_img" src="'+F+'"><table tabindex="0"><thead><tr><th><strong>Content/File</strong></th><th><strong>Instruction</strong></th></tr></thead><tbody><tr><td>color_classification.py</td><td>Color sorting program</td></tr><tr><td>color_tracking.py</td><td>Color tracking program</td></tr><tr><td>face_detection.py</td><td>Face detection program</td></tr><tr><td>gesture_recognition.py</td><td>Gesture recognition program</td></tr><tr><td>remote_control.py</td><td>APP remote control image transmission program</td></tr><tr><td>rock_paper_scissors.py</td><td>Rock-scissors-paper program</td></tr><tr><td>running.py</td><td>APP calling program</td></tr></tbody></table>',62)])])}const N=e(G,[["render",W]]);export{S as __pageData,N as default};
